package org.researchdock.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.text.*;import android.text.style.*;import android.view.*;import android.widget.*;
import org.json.*;import java.io.*;import java.net.URLEncoder;import java.util.concurrent.*;
/** Explicit full-text search with honest offline scope. No model calls. */
public class SearchActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private MobileApi api;private EditText input;private TextView status,scopeLabel;private LinearLayout results;private Spinner range;private CheckBox local;private String company="",industry="",source="";private int generation;private boolean busy;private Button search,clearScope;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextColor(color);t.setTextSize(size);t.setPadding(0,dp(7),0,dp(7));t.setLineSpacing(dp(3),1.08f);return t;}
 private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(ReaderTheme.ACCENT);GradientDrawable g=new GradientDrawable();g.setColor(ReaderTheme.SOFT);g.setCornerRadius(dp(10));b.setBackground(g);b.setStateListAnimator(null);b.setElevation(0);b.setMinHeight(dp(44));b.setPadding(dp(12),dp(6),dp(12),dp(6));b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);api=new MobileApi(this);company=getIntent().getStringExtra("company");industry=getIntent().getStringExtra("industry");source=getIntent().getStringExtra("source");if(company==null)company="";if(industry==null)industry="";if(source==null)source="";
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setFocusableInTouchMode(true);root.setBackgroundColor(ReaderTheme.BACKGROUND);root.setPadding(dp(16),dp(8),dp(16),dp(8));setContentView(root);root.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  LinearLayout top=new LinearLayout(this);top.addView(button("‹ 返回",this::finish));TextView title=text("全文搜索",23,ReaderTheme.ACCENT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setPadding(dp(16),0,0,0);top.addView(title);root.addView(top);
  input=new EditText(this);input.setSingleLine(true);input.setTextSize(16);input.setHint("搜索原文中的词句，至少2个字符");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);input.setTag("fulltext:query");root.addView(input);
  scopeLabel=text("",12,Color.DKGRAY);root.addView(scopeLabel);updateScope();LinearLayout filters=new LinearLayout(this);range=new Spinner(this);range.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"全部日期","今天","最近7天","最近30天","最近90天"}));int days=getIntent().getIntExtra("days",0);range.setSelection(days==1?1:days==7?2:days==30?3:days>0?4:0);filters.addView(range,new LinearLayout.LayoutParams(0,dp(44),1));clearScope=button("清除范围",()->{company="";industry="";source="";range.setSelection(0);updateScope();});filters.addView(clearScope);root.addView(filters);
  local=new CheckBox(this);local.setText("仅搜索本机已缓存正文（可离线）");local.setTextSize(13);root.addView(local);search=button("搜索 · 不调用 AI",this::runSearch);search.setTag("fulltext:search");root.addView(search);input.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){runSearch();return true;}return false;});
  status=text("云端搜索全部已归档正文；PDF、图像和音频仅搜索标题或附件名称，不解析内容。",12,Color.DKGRAY);root.addView(status);ScrollView scroll=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);scroll.addView(results);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(state!=null){input.setText(state.getString("query",""));company=state.getString("company",company);industry=state.getString("industry",industry);source=state.getString("source",source);range.setSelection(state.getInt("range",0));local.setChecked(state.getBoolean("local"));updateScope();}else input.setText(getIntent().getStringExtra("query"));if(input.length()>=2)runSearch();
 }
 private void updateScope(){scopeLabel.setText("资料范围："+(company.isEmpty()&&industry.isEmpty()&&source.isEmpty()?"全部公司与行业":company+(industry.isEmpty()?"":" · "+industry)+(source.isEmpty()?"":" · "+source)));}
 private void setSearching(boolean value){search.setEnabled(!value);input.setEnabled(!value);range.setEnabled(!value);local.setEnabled(!value);clearScope.setEnabled(!value);}
 private String encode(String value)throws Exception{return URLEncoder.encode(value,"UTF-8");}
 private void runSearch(){if(busy)return;String q=input.getText().toString().trim();if(q.codePointCount(0,q.length())<2){input.setError("请输入至少两个字符");return;}final int g=++generation;final String c=company,i=industry,s=source;final int days=new int[]{0,1,7,30,90}[range.getSelectedItemPosition()];boolean offline=local.isChecked();busy=true;setSearching(true);status.setText("正在检索原文…");results.removeAllViews();android.view.inputmethod.InputMethodManager ime=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(ime!=null)ime.hideSoftInputFromWindow(input.getWindowToken(),0);
  worker.execute(()->{try{JSONObject response;boolean fallback=false;if(offline)response=localSearch(q,c,i,s,days);else try{response=api.request("GET","/v1/search?q="+encode(q)+"&company="+encode(c)+"&industry="+encode(i)+"&source="+encode(s)+"&days="+days,null);}catch(Exception error){if(error instanceof MobileApi.Failure)throw error;response=localSearch(q,c,i,s,days);fallback=true;}JSONObject data=response;boolean automatic=fallback;runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;setSearching(false);showResults(data,q,automatic);});}catch(Exception error){runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;setSearching(false);status.setText(error instanceof MobileApi.Failure?error.getMessage():"搜索未完成，请检查网络后重试，或勾选本机缓存搜索。");});}});
 }
 private JSONObject localSearch(String q,String c,String i,String s,int days)throws Exception{JSONArray catalog;try{File file=new File(getFilesDir(),"catalog.json");try(InputStream in=new FileInputStream(file)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>30_000_000)throw new IOException();out.write(b,0,n);}catalog=new JSONArray(out.toString("UTF-8"));}}catch(Exception e){throw new IOException("本机目录不可用，请先同步目录");}if(!api.sameConnection())throw new IOException();return LocalSearch.search(getFilesDir(),catalog,q,c,i,s,days);}
 private void showResults(JSONObject data,String q,boolean automatic){results.removeAllViews();boolean offline=data.optString("scope").startsWith("local");JSONArray rows=data.optJSONArray("results");if(rows==null)rows=new JSONArray();String note="检索「"+q+"」\n"+(automatic?"网络暂不可用，已回退到本机缓存。\n":"")+(offline?"本机当前修订缓存正文，覆盖范围小于云端。":"云端归档正文检索。")+"找到 "+rows.length()+" 条"+(data.optBoolean("has_more")?"（还有更多，请缩小日期或关键词）":"")+" · 不调用 AI";if(offline)note+="\n本次跳过旧修订缓存 "+data.optInt("excluded_stale_caches")+" 项";status.setText(note);if(rows.length()==0)results.addView(text(offline?"本机未找到匹配。可联网搜索全库，或先打开资料缓存正文。":"当前词句或筛选下没有匹配。可清除范围、扩大日期或更换关键词；附件内容未自动解析。",15,Color.DKGRAY));
  for(int n=0;n<rows.length();n++){JSONObject row=rows.optJSONObject(n);if(row==null)continue;JSONObject d=row.optJSONObject("document");if(d==null)continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(12),dp(14),dp(14));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),Color.rgb(235,218,220));card.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));results.addView(card,lp);TextView title=text(d.optString("title"),18,ReaderTheme.ACCENT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);card.addView(title);card.addView(text(d.optString("source_name")+" · "+LibraryViews.date(d.optString("published_at"))+" · r"+d.optInt("revision"),11,Color.DKGRAY));String snippet=row.optString("snippet");SpannableStringBuilder rich=new SpannableStringBuilder(snippet);int start=row.optInt("match_start",-1),end=row.optInt("match_end",-1);if("unicode_codepoints".equals(data.optString("offset_encoding"))&&start>=0&&end>=start&&end<=snippet.codePointCount(0,snippet.length())){start=snippet.offsetByCodePoints(0,start);end=snippet.offsetByCodePoints(0,end);}if(start>=0&&end>start&&end<=rich.length()){rich.setSpan(new BackgroundColorSpan(Color.rgb(255,226,157)),start,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);rich.setSpan(new StyleSpan(Typeface.BOLD),start,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}TextView excerpt=text("",15,Color.rgb(48,38,39));excerpt.setText(rich);card.addView(excerpt);card.addView(text("命中"+("body".equals(row.optString("match_field"))?"正文":"title".equals(row.optString("match_field"))?"标题":"资料信息")+("attachment_only".equals(d.optString("content_kind"))?" · 仅附件，未解析":""),12,Color.DKGRAY));card.addView(button("metadata".equals(row.optString("match_field"))?"阅读原文":"阅读原文并定位",()->startActivity(new Intent(this,SearchReaderActivity.class).putExtra("document",d.toString()).putExtra("query",q).putExtra("cache",row.optString("cache",d.optString("document_id")+".json")))));}
 }
 @Override protected void onSaveInstanceState(Bundle out){out.putString("query",input.getText().toString());out.putString("company",company);out.putString("industry",industry);out.putString("source",source);out.putInt("range",range.getSelectedItemPosition());out.putBoolean("local",local.isChecked());super.onSaveInstanceState(out);}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
